package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

type authorizeRequestBody struct {
	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt"`
}

func authorizeHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		var body authorizeRequestBody
		if fail := readJSON(c, &body, false); fail != nil {
			writeFailure(c, fail)
			return
		}
		decision, fail := service.Decide(authz.DecisionInput{
			Subject:     body.Subject,
			Resource:    body.Resource,
			Operation:   body.Operation,
			EffectiveAt: body.EffectiveAt,
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"decision": decisionResponse(decision)})
	}
}

func decisionResponse(decision *authz.Decision) gin.H {
	if decision.Granted {
		return gin.H{
			"granted":           true,
			"matchedRole":       nullableJSON(decision.Match.Role),
			"matchedPermission": nullableJSON(decision.Match.Permission),
			"matchedScope":      decision.Match.Scope,
		}
	}
	return gin.H{"granted": false, "reason": decision.Reason}
}

func nullableJSON(value string) any {
	if value == "" {
		return nil
	}
	return value
}

func historyHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		subject := c.Query("subject")
		resource := c.Query("resource")
		operation := c.Query("operation")
		if subject == "" || resource == "" || operation == "" {
			writeFailure(c, &authz.Failure{
				Type:    authz.TypeInvalidRequest,
				Field:   "subject",
				Message: "subject, resource and operation query parameters are required",
			})
			return
		}
		events, fail := service.History(authz.HistoryInput{
			Subject:   subject,
			Resource:  resource,
			Operation: operation,
			From:      c.Query("from"),
			To:        c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"events": events})
	}
}
package api

import "net/url"

// pathParam returns a raw path parameter. With UseRawPath enabled, percent
// sequences such as %2F stay encoded, so identifiers containing "/" survive
// inside a single parameter and are decoded here.
func pathParam(c interface{ Param(string) string }, name string) string {
	value := c.Param(name)
	if decoded, err := url.PathUnescape(value); err == nil {
		return decoded
	}
	return value
}
package api

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

// readJSON reads a JSON object body with strict unknown-field and type
// checking. An empty body is allowed when optional is true (timing-only writes
// default every field to its zero value).
func readJSON(c *gin.Context, target any, optional bool) *authz.Failure {
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<20)
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is missing or too large"}
	}
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" {
		if optional {
			return nil
		}
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is empty"}
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		if _, ok := err.(*json.UnmarshalTypeError); ok {
			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: fmt.Sprintf("request body field has the wrong type: %v", err)}
		}
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is not valid JSON for this entry"}
	}
	if decoder.More() {
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body contains more than one JSON value"}
	}
	return nil
}

func writeFailure(c *gin.Context, fail *authz.Failure) {
	if fail == nil {
		return
	}
	status := http.StatusBadRequest
	switch fail.Type {
	case authz.TypeNotFound:
		status = http.StatusNotFound
	case authz.TypeConflict:
		status = http.StatusConflict
	}
	errorObject := gin.H{"type": fail.Type, "message": fail.Message}
	if fail.Field != "" {
		errorObject["field"] = fail.Field
	}
	c.JSON(status, gin.H{"error": errorObject})
}

